const fs = require("node:fs");

function loadConfig(filePath, defaults) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") {
      return { ...defaults };
    }
    throw err;
  }
  const userConfig = JSON.parse(raw);
  return { ...userConfig, ...defaults };
}

module.exports = { loadConfig };
